steps.body:
JavaScript has no built-in linked list. You build one from small node objects, each holding a value and a reference to the next node. Call the class `ListNode`, not `Node`, so it is never confused with Node.js.

```javascript
class ListNode {
  constructor(value, next = null) {
    this.value = value;
    this.next = next;
  }
}
```

`next` holds a reference to another node, not a copy, so `a.next = b` links the real `b`. The last node's `next` is `null`, which marks the end.

A `fromArray` helper builds a list back to front: each new node points at the head built so far, so the order comes out right.

```javascript
let head = null;
for (let i = arr.length - 1; i >= 0; i--) {
  head = new ListNode(arr[i], head);
}
```

To visit every node, start at the head and follow `next` until you reach `null`. Forget `node = node.next` and the loop never ends.

```javascript
let node = head;
while (node !== null) {
  parts.push(node.value);
  node = node.next;
}
```

Joining the values with `" -> "` prints the list as `1 -> 2 -> 3`.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const values = input.trim().split(/\s+/).map(Number);

class ListNode {
  constructor(value, next = null) {
    this.value = value;
    this.next = next;
  }
}

function fromArray(arr) {
  let head = null;
  for (let i = arr.length - 1; i >= 0; i--) {
    head = new ListNode(arr[i], head);
  }
  return head;
}

function listToString(head) {
  const parts = [];
  let node = head;
  while (node !== null) {
    parts.push(node.value);
    node = node.next;
  }
  return parts.join(" -> ");
}

const head = fromArray(values);
let length = 0;
let sum = 0;
let node = head;
while (node !== null) {
  length++;
  sum += node.value;
  node = node.next;
}
console.log(listToString(head));
console.log(`length ${length}, sum ${sum}`);

