steps.body:
Wrap the nodes in a `LinkedList` class that keeps `head` and a `size` counter, so callers never handle nodes directly.

```javascript
addFirst(value) {
  this.head = new ListNode(value, this.head); // O(1)
  this.size++;
}
```

Adding to the end is O(n): walk with `while (tail.next !== null)` to the last node, then set `tail.next`. An empty list has no tail, so check `this.head === null` first.

To delete a node, stop at the node *before* it and skip over it: `prev.next = prev.next.next`. The head has no previous node, so it needs its own case, `this.head = this.head.next`. A dummy node placed before the head removes that special case: start `prev` at the dummy and read the new head back from `dummy.next`. You never free the skipped node. Once nothing references it, the garbage collector reclaims it.

`for...of` and spread look for a method named by the built-in symbol `Symbol.iterator`. The square brackets use that symbol as the method's name, and the `*` makes it a generator method, just like `function*`. Add one and the list walks like an array:

```javascript
*[Symbol.iterator]() {
  let node = this.head;
  while (node !== null) {
    yield node.value;
    node = node.next;
  }
}
```

Now `[...this].join(" -> ")` makes a short `toString()`, and `${list}` uses it.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

class ListNode {
  constructor(value, next = null) {
    this.value = value;
    this.next = next;
  }
}

class LinkedList {
  constructor() {
    this.head = null;
    this.size = 0;
  }

  addFirst(value) {
    this.head = new ListNode(value, this.head);
    this.size++;
  }

  add(value) {
    if (this.head === null) {
      this.head = new ListNode(value);
    } else {
      let tail = this.head;
      while (tail.next !== null) {
        tail = tail.next;
      }
      tail.next = new ListNode(value);
    }
    this.size++;
  }

  remove(value) {
    const dummy = new ListNode(0, this.head);
    let prev = dummy;
    while (prev.next !== null) {
      if (prev.next.value === value) {
        prev.next = prev.next.next;
        this.head = dummy.next;
        this.size--;
        return;
      }
      prev = prev.next;
    }
  }

  *[Symbol.iterator]() {
    let node = this.head;
    while (node !== null) {
      yield node.value;
      node = node.next;
    }
  }

  toString() {
    return [...this].join(" -> ");
  }
}

const list = new LinkedList();
for (const line of lines) {
  const [command, text] = line.trim().split(/\s+/);
  const value = Number(text);
  if (command === "add") {
    list.add(value);
  } else if (command === "addFirst") {
    list.addFirst(value);
  } else {
    list.remove(value);
  }
  console.log(`${command} ${value}: ${list} | size ${list.size}`);
}
let sum = 0;
for (const value of list) {
  sum += value;
}
console.log(`sum ${sum}`);

