steps.body:
To reverse a list in place, flip every `next` arrow. Keep three pointers, and save `next` before you overwrite `curr.next`, or the rest of the list is lost.

```javascript
let prev = null;
let curr = head;
while (curr !== null) {
  const next = curr.next;
  curr.next = prev;
  prev = curr;
  curr = next;
}
return prev; // the new head
```

Fast and slow pointers both start at the head. Each round `slow` moves 1 node and `fast` moves 2. When `fast` runs off the end, `slow` is at the middle, the second middle for an even length. Loop on `fast !== null && fast.next !== null` so `fast.next.next` never reads a property of `null`.

In a cycle, the tail links back to an earlier node, so a plain walk never ends. Once both pointers are inside the cycle, `fast` closes the gap by one node per round, so it cannot jump over `slow` and they must meet. If `slow === fast`, there is a cycle (Floyd's algorithm). If `fast` reaches `null`, there is none. `===` compares node identity, not values.

Find the middle before reversing. Reversing relinks the nodes, so the old head becomes the tail.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

class ListNode {
  constructor(value, next = null) {
    this.value = value;
    this.next = next;
  }
}

function buildList(values, pos) {
  const nodes = values.map((value) => new ListNode(value));
  for (let i = 0; i < nodes.length - 1; i++) {
    nodes[i].next = nodes[i + 1];
  }
  if (pos >= 0) {
    nodes.at(-1).next = nodes[pos];
  }
  return nodes[0];
}

function listToString(head) {
  const parts = [];
  let node = head;
  while (node !== null) {
    parts.push(node.value);
    node = node.next;
  }
  return parts.join(" -> ");
}

function hasCycle(head) {
  let slow = head;
  let fast = head;
  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) {
      return true;
    }
  }
  return false;
}

function middle(head) {
  let slow = head;
  let fast = head;
  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
  }
  return slow;
}

function reverse(head) {
  let prev = null;
  let curr = head;
  while (curr !== null) {
    const next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
  }
  return prev;
}

for (const line of lines) {
  const [pos, ...values] = line.trim().split(/\s+/).map(Number);
  const head = buildList(values, pos);
  if (hasCycle(head)) {
    console.log("cycle");
  } else {
    const mid = middle(head);
    console.log(`middle ${mid.value}, reversed ${listToString(reverse(head))}`);
  }
}

